package com.inovagab.inovagab.service; import com.inovagab.inovagab.dto.*; import com.inovagab.inovagab.model.Projeto; import com.inovagab.inovagab.repository.ProjetoRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ProjetoService { private final ProjetoRepository repo; public ProjetoService(ProjetoRepository repo){this.repo=repo;} public Projeto criar(ProjetoRequest r){return repo.save(new Projeto(r.getNome(),r.getDescricao(),r.getEstrategiaId(),r.getInvestimento(),r.getPrazo()));} public List<Projeto> listar(){return repo.findAll();} public Projeto atualizar(String id,ProjetoRequest r){var p=buscar(id);p.atualizar(r.getNome(),r.getDescricao(),r.getInvestimento(),r.getPrazo(),r.getStatus());return repo.save(p);} public Projeto progresso(String id,ProgressoRequest r){var p=buscar(id);p.progresso(r.getProgresso());return repo.save(p);} public Projeto resultados(String id,ResultadoRequest r){var p=buscar(id);p.resultados(r.getResultados(),r.getRetornoFinanceiro());return repo.save(p);} public void excluir(String id){repo.delete(buscar(id));} private Projeto buscar(String id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Projeto não encontrado"));} }
